import { MapPin, Phone, Mail, Clock, MessageCircle, ArrowRight } from 'lucide-react'
import { Container } from '@/components/ui/container'
import { Heading } from '@/components/ui/heading'
import { Button } from '@/components/ui/button'
import { AnimateOnScroll, AnimatedSectionHeader } from '@/components/ui/animate-on-scroll'
import { cn } from '@/lib/utils'

export interface ContactSectionProps {
  title: string
  subtitle?: string
  address?: string
  neighborhood?: string
  city: string
  phone?: string
  email?: string
  whatsapp?: string
  whatsappMessage?: string
  googleMapsUrl?: string
  /**
   * Opening hours. Accepts either a full weekday map
   *   { "Lunes": "9:00 - 18:00", "Martes": "9:00 - 18:00", ..., "Domingo": "Cerrado" }
   * or a single free-form string like "Lunes a Viernes: 9:00 - 18:00" that
   * renders as one line. The string shape is kept for tenants that don't
   * need a full weekday grid (nexa-propiedades, small-footprint sites);
   * before this was supported, passing a string made the component call
   * `Object.entries` on a string and render one DOM row per character
   * ("0 L 1 u 2 n..." shipped on nexa-propiedades production for weeks).
   */
  hours?: Record<string, string> | string
  /**
   * Optional short note rendered below the weekday list — useful for
   * "Tiendas en shopping abren todos los días hasta 21h" kind of
   * caveats that don't fit into a weekday grid.
   */
  hoursNote?: string
  /** Locale-keyed UI labels. Falls back to CONTACT_LABELS inline constant when not supplied. */
  labels?: Record<string, {
    address: string
    contact: string
    whatsappCta: string
    email: string
    hours: string
    mapAlt: (city: string) => string
    weekdayOrder: string[]
  }>
  __locale?: string
}

const CONTACT_LABELS: Record<string, {
  address: string
  contact: string
  whatsappCta: string
  email: string
  hours: string
  mapAlt: (city: string) => string
  weekdayOrder: string[]
}> = {
  en: {
    address: 'Address',
    contact: 'Contact',
    whatsappCta: 'Message on WhatsApp',
    email: 'Email',
    hours: 'Business hours',
    mapAlt: (city) => `Map of ${city}`,
    weekdayOrder: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'],
  },
  es: {
    address: 'Dirección',
    contact: 'Contacto',
    whatsappCta: 'Escribir por WhatsApp',
    email: 'Email',
    hours: 'Horario de atención',
    mapAlt: (city) => `Mapa de ${city}`,
    weekdayOrder: ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'],
  },
}

function orderHours(
  hours: Record<string, string>,
  preferred: string[],
): Array<[string, string]> {
  const entries = Object.entries(hours)
  // Index by normalized (lowercased) day name for robust matching.
  const normalize = (s: string) => s.toLowerCase()
  const byKey = new Map(entries.map(([k, v]) => [normalize(k), [k, v] as [string, string]]))
  const ordered: Array<[string, string]> = []
  for (const day of preferred) {
    const hit = byKey.get(normalize(day))
    if (hit) {
      ordered.push(hit)
      byKey.delete(normalize(day))
    }
  }
  // Append any remaining unmatched keys in insertion order
  for (const [, pair] of byKey) ordered.push(pair)
  return ordered
}

/**
 * Enhanced Contact section with improved layout and UX.
 *
 * Improvements:
 * - Better visual hierarchy with cards
 * - Improved spacing and typography
 * - Enhanced WhatsApp CTA
 * - Better map container styling
 * - Cleaner info item design
 */
export function ContactSection({
  title,
  subtitle,
  address,
  neighborhood,
  city,
  phone,
  email,
  whatsapp,
  whatsappMessage,
  googleMapsUrl,
  hours,
  hoursNote,
  __locale = 'es',
  labels: labelsProp,
}: ContactSectionProps) {
  const resolvedLabels = labelsProp ?? CONTACT_LABELS
  const labels = resolvedLabels[__locale] ?? resolvedLabels.es
  const hasContactInfo = phone || email || whatsapp
  // `hours` can be a free-form string or a weekday map. Normalize the
  // two early so downstream rendering code branches in exactly one place.
  const hoursIsString = typeof hours === 'string'
  const hoursMap = !hoursIsString && hours ? hours : undefined
  const hasHours = hoursIsString
    ? (hours as string).trim().length > 0
    : hoursMap
    ? Object.keys(hoursMap).length > 0
    : false
  const whatsappHref = whatsapp
    ? `https://wa.me/${whatsapp.replace(/\D/g, '')}${whatsappMessage ? `?text=${encodeURIComponent(whatsappMessage)}` : ''}`
    : ''

  return (
    <section id="contacto" className="bg-[var(--surface)] py-20 sm:py-28 lg:py-32">
      <Container>
        <AnimatedSectionHeader className="mb-12 sm:mb-16">
          <Heading level={2}
            style={{
              fontSize: 'clamp(1.875rem, 4vw, 2.75rem)',
              lineHeight: '1.15',
              letterSpacing: '-0.02em',
            }}
          >
            {title}
          </Heading>
          {subtitle && (
            <p className="mt-5 max-w-2xl text-lg sm:text-xl leading-relaxed"
              style={{ color: 'var(--text-light)' }}
            >
              {subtitle}
            </p>
          )}
        </AnimatedSectionHeader>

        <div className={`grid gap-8 lg:gap-12 ${googleMapsUrl ? 'lg:grid-cols-2' : ''}`}>
          {/* Contact Info Cards */}
          <AnimateOnScroll>
            <div className="space-y-6">
              {/* Address Card */}
              <div 
                className="flex gap-5 p-6 rounded-2xl transition-all duration-300 hover:shadow-md"
                style={{
                  backgroundColor: 'var(--background)',
                  border: '1px solid rgba(0,0,0,0.06)',
                }}
              >
                <div 
                  className="flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center"
                  style={{
                    backgroundColor: 'rgba(30, 58, 95, 0.08)',
                  }}
                >
                  <MapPin size={22} style={{ color: 'var(--primary)' }} />
                </div>
                <div>
                  <Heading level={3} 
                    className="mb-2 text-base font-bold uppercase tracking-wide"
                    style={{ color: 'var(--text)' }}
                  >
                    {labels.address}
                  </Heading>
                  <p className="leading-relaxed" style={{ color: 'var(--text-light)' }}>
                    {address && <span className="block">{address}</span>}
                    {neighborhood && <span>{neighborhood}, </span>}
                    <span className="font-medium" style={{ color: 'var(--text)' }}>{city}</span>
                  </p>
                </div>
              </div>

              {/* Phone/WhatsApp Card */}
              {hasContactInfo && (
                <div 
                  className="flex gap-5 p-6 rounded-2xl transition-all duration-300 hover:shadow-md"
                  style={{
                    backgroundColor: 'var(--background)',
                    border: '1px solid rgba(0,0,0,0.06)',
                  }}
                >
                  <div 
                    className="flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center"
                    style={{
                      backgroundColor: 'rgba(184, 134, 11, 0.12)',
                    }}
                  >
                    <Phone size={22} style={{ color: 'var(--secondary)' }} />
                  </div>
                  <div className="flex-1">
                    <Heading level={3} 
                      className="mb-2 text-base font-bold uppercase tracking-wide"
                      style={{ color: 'var(--text)' }}
                    >
                      {labels.contact}
                    </Heading>
                    {phone && (
                      <a
                        href={`tel:${phone}`}
                        className="block mb-2 text-lg font-medium transition-colors hover:underline"
                        style={{ color: 'var(--primary)' }}
                      >
                        {phone}
                      </a>
                    )}
                    {whatsapp && !phone && (
                      <p
                        className="block mb-2 text-lg font-medium"
                        style={{ color: 'var(--primary)' }}
                      >
                        {whatsapp}
                      </p>
                    )}
                    {whatsapp && (
                      <a
                        href={whatsappHref}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-2 mt-2 px-5 py-2.5 rounded-lg text-sm font-semibold transition-all duration-300 hover:scale-[1.02]"
                        style={{
                          backgroundColor: '#25D366',
                          color: '#ffffff',
                          boxShadow: '0 4px 12px rgba(37, 211, 102, 0.3)',
                        }}
                      >
                        <MessageCircle size={18} />
                        {labels.whatsappCta}
                        <ArrowRight size={14} />
                      </a>
                    )}
                  </div>
                </div>
              )}

              {/* Email Card */}
              {email && (
                <div 
                  className="flex gap-5 p-6 rounded-2xl transition-all duration-300 hover:shadow-md"
                  style={{
                    backgroundColor: 'var(--background)',
                    border: '1px solid rgba(0,0,0,0.06)',
                  }}
                >
                  <div 
                    className="flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center"
                    style={{
                      backgroundColor: 'rgba(30, 58, 95, 0.08)',
                    }}
                  >
                    <Mail size={22} style={{ color: 'var(--primary)' }} />
                  </div>
                  <div>
                    <Heading level={3} 
                      className="mb-2 text-base font-bold uppercase tracking-wide"
                      style={{ color: 'var(--text)' }}
                    >
                      {labels.email}
                    </Heading>
                    <a 
                      href={`mailto:${email}`}
                      className="text-lg font-medium transition-colors hover:underline"
                      style={{ color: 'var(--primary)' }}
                    >
                      {email}
                    </a>
                  </div>
                </div>
              )}

              {/* Hours Card */}
              {hasHours && (
                <div 
                  className="flex gap-5 p-6 rounded-2xl transition-all duration-300 hover:shadow-md"
                  style={{
                    backgroundColor: 'var(--background)',
                    border: '1px solid rgba(0,0,0,0.06)',
                  }}
                >
                  <div 
                    className="flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center"
                    style={{
                      backgroundColor: 'rgba(30, 58, 95, 0.08)',
                    }}
                  >
                    <Clock size={22} style={{ color: 'var(--primary)' }} />
                  </div>
                  <div className="flex-1">
                    <Heading level={3} 
                      className="mb-3 text-base font-bold uppercase tracking-wide"
                      style={{ color: 'var(--text)' }}
                    >
                      {labels.hours}
                    </Heading>
                    {hoursIsString ? (
                      <p className="text-sm sm:text-base" style={{ color: 'var(--text-light)' }}>
                        {hours as string}
                      </p>
                    ) : (
                      <dl className="space-y-2">
                        {orderHours(hoursMap as Record<string, string>, labels.weekdayOrder).map(([day, time]) => (
                          <div key={day}
                            className="flex justify-between gap-4 text-sm sm:text-base py-1 border-b border-[var(--border)] last:border-0"
                          >
                            <dt style={{ color: 'var(--text)' }}>{day}</dt>
                            <dd className="font-medium" style={{ color: 'var(--text-light)' }}>{time}</dd>
                          </div>
                        ))}
                      </dl>
                    )}
                    {hoursNote && (
                      <p className="mt-3 text-xs italic" style={{ color: 'var(--text-light)' }}>
                        {hoursNote}
                      </p>
                    )}
                  </div>
                </div>
              )}
            </div>
          </AnimateOnScroll>

          {/* Map — only render when a Google Maps embed URL is provided.
              Without a street-level address the fallback is visual noise,
              especially on dark themes where it collapses to a near-empty
              box (looked broken on Dayah). Remote-only businesses skip this. */}
          {googleMapsUrl && (
            <AnimateOnScroll stagger={1}>
              <div
                className="h-full min-h-[400px] overflow-hidden rounded-2xl"
                style={{
                  backgroundColor: 'var(--surface-light)',
                  boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
                  border: '1px solid rgba(0,0,0,0.06)',
                }}
              >
                <iframe
                  src={googleMapsUrl}
                  width="100%"
                  height="100%"
                  className="min-h-[400px] lg:min-h-full border-0"
                  allowFullScreen
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                  title={labels.mapAlt(city)}
                  style={{ filter: 'grayscale(15%) contrast(105%)' }}
                />
              </div>
            </AnimateOnScroll>
          )}
        </div>
      </Container>
    </section>
  )
}

export default ContactSection
